import { observable } from '@trpc/server/observable';
import type { AnyRouter, inferRouterContext } from '@trpc/server/unstable-core-do-not-import';
import { callProcedure } from '@trpc/server/unstable-core-do-not-import';
import { TRPCClientError } from '../TRPCClientError';
import type { TRPCLink } from './types';

export interface LocalLinkOptions<TRouter extends AnyRouter> {
  router: TRouter;
  createContext?: () => Promise<inferRouterContext<TRouter>> | inferRouterContext<TRouter>;
}

export function localLink<TRouter extends AnyRouter>(
  opts: LocalLinkOptions<TRouter>,
): TRPCLink<TRouter> {
  return () =>
    ({ op }) =>
      observable((observer) => {
        let isDone = false;
        async function execute() {
          try {
            const ctx = await opts.createContext?.();
            const result = await callProcedure({
              router: opts.router,
              path: op.path,
              getRawInput: async () => op.input,
              type: op.type,
              ctx,
              signal: op.signal ?? undefined,
            });

            if (!isDone) {
              observer.next({ result: { type: 'data', data: result } });
              observer.complete();
            }
          } catch (err) {
            if (!isDone) {
              observer.error(TRPCClientError.from(err));
            }
          }
        }
        execute();

        return () => {
          isDone = true;
        };
      });
}
EOF

cat << 'EOF' > packages/client/src/links/localLink.test.ts
import { initTRPC } from '@trpc/server';
import { z } from 'zod';
import { localLink } from './localLink';
import { createTRPCClient } from '../createTRPCClient';
import superjson from 'superjson';

test('localLink with transformer', async () => {
  const t = initTRPC.create({ transformer: superjson });
  const router = t.router({
    date: t.procedure.input(z.date()).query(({ input }) => {
      return new Date(input.getTime() + 1000);
    }),
  });

  const client = createTRPCClient<typeof router>({
    links: [localLink({ router, transformer: superjson })],
  });

  const d = new Date('2022-01-01T00:00:00.000Z');
  const res = await client.date.query(d);
  expect(res).toEqual(new Date('2022-01-01T00:00:01.000Z'));
});
EOF
